/bin/bash -lc "cat > src/App.tsx <<'EOF'
import {useState} from 'react';
import {AsideHeader} from '@gravity-ui/navigation';
import {Button, Switch, Text, ThemeProvider} from '@gravity-ui/uikit';
import './App.css';

type Page = 'overview' | 'projects' | 'about';

const pageCopy: Record<Page, {eyebrow: string; title: string; description: string}> = {
  overview: {
    eyebrow: 'РАБОЧЕЕ ПРОСТРАНСТВО',
    title: 'Хороший день для больших планов',
    description: 'Соберите задачи в одном месте и двигайтесь к важному в комфортном темпе.',
  },
  projects: {
    eyebrow: 'ВАШИ ПРОЕКТЫ',
    title: 'От идеи к результату',
    description: 'Три направления, которые сейчас задают ритм вашей работе.',
  },
  about: {
    eyebrow: 'О ПРОСТРАНСТВЕ',
    title: 'Меньше шума. Больше смысла.',
    description: 'Небольшой пример приложения на Gravity UI: навигация, страницы и тема под вашим контролем.',
  },
};

const projects = [
  {name: 'Новый сайт', tag: 'ДИЗАЙН', progress: 72, note: 'Финальные правки главной страницы'},
  {name: 'Осенний запуск', tag: 'МАРКЕТИНГ', progress: 46, note: 'Подготовить план публикаций'},
  {name: 'Клиентский портал', tag: 'РАЗРАБОТКА', progress: 28, note: 'Согласовать структуру кабинета'},
];

export function App() {
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [page, setPage] = useState<Page>('overview');
  const [compact, setCompact] = useState(false);
  const copy = pageCopy[page];

  const changePage = (next: Page) => {
    setPage(next);
    window.history.replaceState(null, '', "'`#${next}`);
  };

  return (
    <ThemeProvider theme={theme}>
      <div className="app-shell">
        <AsideHeader
          logo={{text: '"'ТИХО', href: '#overview'}}
          compact={compact}
          onChangeCompact={setCompact}
          menuItems={[
            {id: 'overview', title: 'Обзор', current: page === 'overview', onItemClick: () => changePage('overview')},
            {id: 'projects', title: 'Проекты', current: page === 'projects', onItemClick: () => changePage('projects')},
            {id: 'about', title: 'О проекте', current: page === 'about', onItemClick: () => changePage('about')},
          ]}
          renderFooter={() => (
            <div className=\"theme-control\">
              <span className=\"theme-label\">Тёмная тема</span>
              <Switch size=\"m\" checked={theme === 'dark'} onChange={(event) => setTheme(event.target.checked ? 'dark' : 'light')} />
            </div>
          )}
          renderContent={() => (
            <main className=\"page-content\">
              <header className=\"topbar\">
                <span className=\"topbar-label\">ЛИЧНЫЙ ПЛАНЕР</span>
                <span className=\"date-label\">СРЕДА · 5 НОЯБРЯ</span>
              </header>
              <section className=\"hero\">
                <div className=\"hero-copy\">
                  <Text variant=\"caption-2\" className=\"eyebrow\">{copy.eyebrow}</Text>
                  <Text variant=\"header-1\" className=\"hero-title\">{copy.title}</Text>
                  <Text variant=\"body-2\" color=\"secondary\" className=\"hero-description\">{copy.description}</Text>
                  <Button view=\"action\" size=\"l\" onClick={() => changePage(page === 'projects' ? 'overview' : 'projects')}>
                    {page === 'projects' ? 'Вернуться к обзору' : 'Посмотреть проекты'}
                  </Button>
                </div>
                <div className=\"hero-art\" aria-hidden=\"true\">
                  <div className=\"sun-disc\" />
                  <div className=\"art-line art-line-one\" />
                  <div className=\"art-line art-line-two\" />
                  <span className=\"art-caption\">FOCUS<br/>ON WHAT<br/>MATTERS</span>
                </div>
              </section>
              {page === 'about' ? (
                <section className=\"about-panel\">
                  <Text variant=\"subheader-1\">Пространство для ясных мыслей</Text>
                  <Text variant=\"body-2\" color=\"secondary\">Переходите между разделами через меню слева, а переключатель темы всегда остаётся под рукой. Ваш выбор темы применяется ко всему интерфейсу.</Text>
                  <div className=\"about-stats\"><div><strong>03</strong><span>страницы</span></div><div><strong>02</strong><span>темы</span></div><div><strong>01</strong><span>пространство</span></div></div>
                </section>
              ) : (
                <section className=\"projects-section\">
                  <div className=\"section-heading\">
                    <div><Text variant=\"subheader-1\">{page === 'projects' ? 'Все проекты' : 'В фокусе'}</Text><Text variant=\"caption-2\" color=\"secondary\">Текущий прогресс и ближайший шаг</Text></div>
                    <Button view=\"flat-secondary\" onClick={() => changePage('projects')}>Все проекты ↗</Button>
                  </div>
                  <div className=\"project-grid\">
                    {projects.map((project, index) => (
                      <article className={"'`project-card project-card-${index + 1}`} key={project.name}>
                        <div className="card-top"><span className="project-tag">{project.tag}</span><span className="project-index">0{index + 1}</span></div>
                        <Text variant="subheader-2">{project.name}</Text>
                        <Text variant="body-2" color="secondary" className="project-note">{project.note}</Text>
                        <div className="progress-row"><div className="progress-track"><span style={{width: `${project.progress}%`}} /></div><span>{project.progress}%</span></div>
                      </article>
                    ))}
                  </div>
                </section>
              )}
              <footer className="page-footer"><span>ТИШЕ — ЗНАЧИТ ЯСНЕЕ</span><span>СДЕЛАНО ДЛЯ ФОКУСА</span></footer>
            </main>
          )}
        />
      </div>
    </ThemeProvider>
  );
}
EOF
cat > src/App.css <<'"'EOF'
.app-shell { min-height: 100vh; background: var(--g-color-base-background); color: var(--g-color-text-primary); }
.page-content { min-height: 100vh; padding: 0 48px; box-sizing: border-box; display: flex; flex-direction: column; max-width: 1600px; margin: 0 auto; }
.topbar { height: 76px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--g-color-line-generic); flex-shrink: 0; }
.topbar-label, .date-label, .eyebrow, .page-footer, .project-tag, .project-index { font-size: 10px; letter-spacing: .13em; font-weight: 600; }
.topbar-label { color: var(--g-color-text-secondary); }
.date-label { color: var(--g-color-text-hint); }
.hero { min-height: 360px; display: grid; grid-template-columns: 1.15fr .85fr; align-items: center; gap: 32px; padding: 36px 0 44px; border-bottom: 1px solid var(--g-color-line-generic); }
.hero-copy { max-width: 590px; }
.eyebrow { color: var(--g-color-text-brand); }
.hero-title { display: block; max-width: 620px; margin: 18px 0 14px; line-height: 1.12; }
.hero-description { display: block; max-width: 470px; margin-bottom: 26px; }
.hero-art { height: 270px; overflow: hidden; position: relative; background: var(--g-color-base-neutral-light); }
.sun-disc { width: 196px; height: 196px; border-radius: 50%; background: var(--g-color-base-brand); opacity: .88; position: absolute; top: 38px; left: 23%; }
.art-line { position: absolute; width: 130%; height: 1px; background: var(--g-color-line-generic); left: -10%; transform: rotate(-26deg); }
.art-line-one { top: 82px; }.art-line-two { top: 185px; transform: rotate(26deg); }
.art-caption { position: absolute; right: 20px; bottom: 18px; font-size: 9px; line-height: 1.5; letter-spacing: .16em; color: var(--g-color-text-primary); }
.projects-section { padding: 34px 0 46px; }
.section-heading { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }
.section-heading > div { display: grid; gap: 6px; }
.project-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }
.project-card { min-height: 178px; padding: 20px; background: var(--g-color-base-float); border: 1px solid var(--g-color-line-generic); display: flex; flex-direction: column; align-items: flex-start; }
.card-top { width: 100%; display: flex; justify-content: space-between; margin-bottom: 22px; }
.project-tag { color: var(--g-color-text-secondary); font-size: 9px; }.project-index { color: var(--g-color-text-hint); font-size: 9px; }
.project-note { display: block; margin-top: 6px; }
.progress-row { width: 100%; margin-top: auto; padding-top: 20px; display: flex; align-items: center; gap: 12px; font-size: 11px; color: var(--g-color-text-secondary); }
.progress-track { height: 3px; flex: 1; background: var(--g-color-base-generic); }.progress-track span { display: block; height: 100%; background: var(--g-color-base-brand); }
.about-panel { margin: 36px 0 46px; padding: 30px; border: 1px solid var(--g-color-line-generic); max-width: 800px; }
.about-panel > :nth-child(2) { display: block; max-width: 600px; margin-top: 10px; }
.about-stats { display: flex; gap: 70px; margin-top: 34px; }.about-stats div { display: grid; gap: 5px; }.about-stats strong { font-size: 26px; font-weight: 500; }.about-stats span { color: var(--g-color-text-secondary); font-size: 12px; }
.page-footer { margin-top: auto; min-height: 54px; border-top: 1px solid var(--g-color-line-generic); display: flex; justify-content: space-between; align-items: center; color: var(--g-color-text-hint); font-size: 9px; }
.theme-control { padding: 16px; display: flex; align-items: center; justify-content: space-between; gap: 14px; }.theme-label { font-size: 12px; color: var(--g-color-text-secondary); }
@media (max-width: 800px) { .page-content { padding: 0 24px; }.hero { grid-template-columns: 1fr; }.hero-art { height: 210px; }.project-grid { grid-template-columns: 1fr; }.project-card { min-height: 155px; } }
@media (max-width: 480px) { .page-content { padding: 0 16px; }.topbar { height: 60px; }.hero { padding: 28px 0; }.hero-title { font-size: 30px; }.hero-art { height: 170px; }.about-panel { padding: 20px; }.about-stats { gap: 30px; }.page-footer { font-size: 8px; letter-spacing: .08em; } }
EOF
